SELECT COUNT(*) 
FROM superhero 
WHERE full_name IS NULL;

SELECT AVG(s.weight_kg) 
FROM superhero s
WHERE s.gender_id = (SELECT id FROM gender WHERE gender = 'Female');

SELECT CAST(SUM(CASE WHEN L.UA <= '8.0' AND P.SEX = 'M' THEN 1 ELSE 0 END) AS FLOAT) / NULLIF(CAST(SUM(CASE WHEN L.UA <= '6.5' AND P.SEX = 'F' THEN 1 ELSE 0 END) AS FLOAT), 0) AS ratio;
FROM Patient P
JOIN Laboratory L ON P.ID = L.ID;

SELECT SUM(CASE WHEN L.Laboratory.PLT < 100 THEN 1 ELSE 0 END) - SUM(CASE WHEN L.Laboratory.PLT > 400 THEN 1 ELSE 0 END) AS difference;
FROM Patient P
JOIN Examination E ON P.ID = E.ID
JOIN Laboratory L ON P.ID = L.ID
WHERE (L.Laboratory.PLT <= 100 OR L.Laboratory.PLT >= 400);

SELECT SUM(cost) AS total_cost
FROM expense
WHERE expense_description = 'Pizza';

SELECT MAX(Consumption) 
FROM yearmonth 
WHERE Date LIKE '2012_%';

SELECT MIN(Date) AS start_date, MAX(Date) AS end_date
FROM transactions_1k
WHERE GasStationID IN (SELECT GasStationID FROM gasstations WHERE ChainID = 11);
